require_once __DIR__.'/../api/bootstrap.php';require_login();$m=current_medico();$err='';$aid=(int)($_GET['atendimento_id']??0);
$s=db()->prepare('SELECT id,nome FROM pacientes WHERE medico_id=? ORDER BY nome');$s->execute([$m['id']]);$ps=$s->fetchAll();
$models=db()->prepare("SELECT id,nome,conteudo FROM modelos_documento WHERE medico_id=? AND tipo='LAUDO' AND ativo=1 ORDER BY nome");$models->execute([$m['id']]);$models=$models->fetchAll();
$pre=[];$selectedPatient=(int)($_GET['paciente_id']??0);if($aid){$s=db()->prepare('SELECT * FROM atendimentos WHERE id=? AND medico_id=?');$s->execute([$aid,$m['id']]);$pre=$s->fetch()?:[];$selectedPatient=(int)($pre['paciente_id']??$selectedPatient);}
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$pid=(int)($_POST['paciente_id']??0);$p=patient_for_doctor($pid,$m['id']);$v=[];foreach(['titulo','historico_clinico','avaliacao','exames','cid_codigo','cid_descricao','atividade_habitual','repercussao','periodo_estimado','incapacidade_restricao','conclusao','conteudo_personalizado'] as $f)$v[$f]=trim($_POST[$f]??'');$mid=(int)($_POST['modelo_id']??0);
if(!$p)$err='Paciente inválido.';elseif($v['conclusao']==='')$err='A conclusão é obrigatória.';elseif(empty($_POST['confirmar']))$err='Confirme a revisão médica.';
else{$code=unique_code('LAUD');$q=db()->prepare('INSERT INTO laudos(paciente_id,medico_id,atendimento_id,codigo_validacao,data_emissao,titulo,conteudo_personalizado,historico_clinico,avaliacao,exames,cid_codigo,cid_descricao,atividade_habitual,repercussao,periodo_estimado,incapacidade_restricao,modelo_id,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$pid,$m['id'],$aid?:null,$code,date('Y-m-d H:i:s'),$v['titulo']?:'Laudo Médico',$v['conteudo_personalizado'],$v['historico_clinico'],$v['avaliacao'],$v['exames'],$v['cid_codigo'],$v['cid_descricao'],$v['atividade_habitual'],$v['repercussao'],$v['periodo_estimado'],$v['incapacidade_restricao'],$mid?:null,'EMITIDO']);$id=db()->lastInsertId();db()->prepare('INSERT INTO documentos_versoes(tipo,documento_id,medico_id,versao,conteudo) VALUES(?,?,?,?,?)')->execute(['LAUDO',$id,$m['id'],1,$v['conteudo_personalizado']]);audit_log('emitir_laudo','laudos',$id,['codigo'=>$code,'modelo_id'=>$mid]);header('Location:view.php?id='.$id);exit;}}
render_header('Novo laudo');?><h1>Laudo médico</h1><?php if($err):?><div class="error"><?=e($err)?></div><?php endif;?>
