<?php foreach([['historico_clinico','História clínica',$pre['historia_clinica']??''],['avaliacao','Avaliação / exame físico',$pre['exame_fisico']??''],['exames','Exames complementares',$pre['exames_apresentados']??''],['repercussao','Repercussão funcional',$pre['capacidade_impacto']??''],['incapacidade_restricao','Incapacidade/restrições',$pre['capacidade_restricoes']??''],['conclusao','Conclusão médica','']] as $f):?><div class="card"><label><?=e($f[1])?></label><textarea name="<?=e($f[0])?>" <?=($f[0]==='conclusao'?'required':'')?>><?=e($f[2])?></textarea></div><?php endforeach;?>
