<script>
const modelo=document.getElementById('modelo'),texto=document.getElementById('texto');modelo.onchange=()=>{const o=modelo.selectedOptions[0];if(o&&o.dataset.text)texto.value=o.dataset.text;};
const c=document.getElementById('cc'),d=document.getElementById('cd'),r=document.getElementById('cr');let t;c.oninput=()=>{clearTimeout(t);if(c.value.length<2){r.innerHTML='';return}t=setTimeout(()=>fetch('<?=e(medical_url('cid/search.php'))?>?q='+encodeURIComponent(c.value)).then(x=>x.json()).then(a=>r.innerHTML=a.map(x=>'<button type="button" data-c="'+x.codigo.replaceAll('"','&quot;')+'" data-d="'+x.descricao.replaceAll('"','&quot;')+'"><b>'+x.codigo+'</b> — '+x.descricao+'</button>').join('')).then(()=>r.querySelectorAll('button').forEach(b=>b.onclick=()=>{c.value=b.dataset.c;d.value=b.dataset.d;r.innerHTML='';})),250)};
</script><?php render_footer();